25	FtsRecallNode::FtsRecallNode(Segment::Ptr segment, QueryInfo::Ptr query_info,
26	                             DocFilter::Ptr doc_filter, int batch_size)
27	    : segment_(std::move(segment)),
28	      query_info_(std::move(query_info)),
29	      doc_filter_(std::move(doc_filter)),
30	      fetched_columns_(query_info_->get_all_fetched_scalar_field_names()),
31	      batch_size_(batch_size) {
32	  auto table = segment_->fetch(fetched_columns_, std::vector<int>{});
33	  // Append BM25 score column so downstream fill_doc_score() surfaces it to
34	  // the Python Doc.score, matching the vector-recall path.
35	  schema_ = Util::append_field(*table->schema(), kFieldScore, arrow::float32());
36	}
37	
38	arrow::AsyncGenerator<std::optional<cp::ExecBatch>> FtsRecallNode::gen() {
39	  auto state_ptr = std::make_shared<State>();
40	  return [self = shared_from_this(), state_ptr = std::move(state_ptr)]()
41	             -> arrow::Future<std::optional<cp::ExecBatch>> {
42	    auto &state = *state_ptr;
43	
44	    if (!state.iter_) {
45	      auto fts_ret = self->prepare();
46	      if (!fts_ret) {
47	        return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
48	            arrow::Status::ExecutionError("prepare fts failed:",
49	                                          fts_ret.error().c_str()));
50	      }
51	      state.fts_result_ = fts_ret.value();
52	      state.iter_ = state.fts_result_->create_iterator();
53	    }
54	
55	    if (!state.iter_->valid()) {
56	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
57	          std::nullopt);
58	    }
59	
60	    std::vector<int> indices;
61	    indices.reserve(self->batch_size_);
62	    arrow::FloatBuilder score_builder;
63	    for (int i = 0; state.iter_->valid() && i < self->batch_size_;
64	         i++, state.iter_->next()) {
65	      indices.push_back(state.iter_->doc_id());
66	      auto s = score_builder.Append(state.iter_->score());
67	      if (!s.ok()) {
68	        return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
69	            arrow::Status::ExecutionError("score builder append failed:",
70	                                          s.ToString()));
71	      }
72	    }
73	    if (indices.empty()) {
74	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
75	          std::nullopt);
76	    }
77	
78	    auto table = self->segment_->fetch(self->fetched_columns_, indices);
79	    if (!table) {
80	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
81	          arrow::Status::UnknownError("fetch table failed"));
82	    }
83	    auto batch = table->CombineChunksToBatch();
84	    if (!batch.ok()) {
85	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
86	          arrow::Status::ExecutionError("combine chunks to batch failed:",
87	                                        batch.status().ToString()));
88	    }
89	    auto score_array = score_builder.Finish();
90	    if (!score_array.ok()) {
91	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
92	          arrow::Status::ExecutionError("finish score builder failed:",
93	                                        score_array.status().ToString()));
94	    }
95	    auto record_batch = std::move(batch.ValueUnsafe());
96	    auto with_score =
97	        record_batch->AddColumn(record_batch->num_columns(), kFieldScore,
98	                                score_array.MoveValueUnsafe());
99	    if (!with_score.ok()) {
100	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
101	          arrow::Status::ExecutionError("add score column failed:",
102	                                        with_score.status().ToString()));
103	    }
104	    cp::ExecBatch exec_batch(*with_score.ValueUnsafe());
105	    return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
106	        std::move(exec_batch));
107	  };
108	}
109	
110	Result<FtsIndexResults::Ptr> FtsRecallNode::prepare() {
111	  auto filter_status = doc_filter_->compute_filter();
112	  if (!filter_status.ok()) {
113	    return tl::make_unexpected(filter_status);
114	  }
115	
116	  const auto &fts_cond = query_info_->fts_cond_info();
117	  if (!fts_cond) {
118	    return tl::make_unexpected(
119	        Status::InvalidArgument("FtsRecallNode: no fts_cond_info in query"));
120	  }
121	
122	  fts::FtsQueryParams params;
123	  params.topk = query_info_->query_topn();
124	  // Brute-force path: get_bf_by_keys_and_update also clears invert_filter_
125	  // when it returns ids, so the filter set below won't double-check them.
126	  if (auto bf_keys = doc_filter_->get_bf_by_keys_and_update(
127	          GlobalConfig::Instance().fts_brute_force_by_keys_ratio())) {
128	    params.candidate_ids = std::move(bf_keys.value());
129	  }
130	  // Push down remaining filters (delete / forward) so filtered docs are
131	  // skipped during scoring and we still return up to topk results.
132	  params.filter = doc_filter_->empty() ? nullptr : doc_filter_;
133	
134	  auto results =
135	      segment_->fts_search(fts_cond->field_name, *fts_cond->fts_ast, params);
136	  if (!results) {
137	    return tl::make_unexpected(results.error());
138	  }
139	
140	  return std::make_shared<FtsIndexResults>(std::move(results.value()));
141	}
142	
143	}  // namespace zvec::sqlengine
