27	class InvertedSearchResult
28	    : public IndexResults,
29	      public std::enable_shared_from_this<InvertedSearchResult> {
30	 public:
31	  using Ptr = std::shared_ptr<InvertedSearchResult>;
32	
33	
34	  class Filter : public IndexFilter {
35	   public:
36	    explicit Filter(std::shared_ptr<const InvertedSearchResult> result)
37	        : result_(std::move(result)) {};
38	
39	    bool is_filtered(uint64_t id) const override {
40	      return !result_->contains(id);
41	    }
42	
43	   private:
44	    const std::shared_ptr<const InvertedSearchResult> result_{};
45	  };
46	
47	
48	  const IndexFilter::Ptr make_filter() const {
49	    return bitmap_ ? std::make_shared<Filter>(shared_from_this()) : nullptr;
50	  }
51	
52	
53	  explicit InvertedSearchResult() {}
54	
55	
56	  explicit InvertedSearchResult(roaring_bitmap_t *bitmap) : bitmap_(bitmap) {}
57	
58	
59	  ~InvertedSearchResult() override {
60	    destroy_bitmap();
61	  }
62	
63	
64	  InvertedSearchResult(const InvertedSearchResult &) = delete;
65	  InvertedSearchResult(InvertedSearchResult &&) = delete;
66	  InvertedSearchResult &operator=(const InvertedSearchResult &) = delete;
67	  InvertedSearchResult &operator=(InvertedSearchResult &&) = delete;
68	
69	
70	  bool contains(uint32_t id) const {
71	    if (bitmap_) {
72	      return roaring_bitmap_contains(bitmap_, id);
73	    } else {
74	      return false;
75	    }
76	  }
77	
78	
79	  size_t count() const override {
80	    if (bitmap_) {
81	      return roaring_bitmap_get_cardinality(bitmap_);
82	    } else {
83	      return 0;
84	    }
85	  }
86	
87	
88	  class InvertedIndexIterator : public Iterator {
89	   public:
90	    explicit InvertedIndexIterator(
91	        std::shared_ptr<const InvertedSearchResult> result)
92	        : result_(result) {
93	      if (result_->bitmap_) {
94	        iter_ = roaring_create_iterator(result_->bitmap_);
95	      }
96	    }
97	
98	    ~InvertedIndexIterator() override {
99	      if (iter_) {
100	        roaring_free_uint32_iterator(iter_);
101	      }
102	    }
103	
104	    idx_t doc_id() const override {
105	      if (!iter_) {
106	        return INVALID_DOC_ID;
107	      }
108	      if (iter_->has_value) {
109	        return iter_->current_value;
110	      } else {
111	        return INVALID_DOC_ID;
112	      }
113	    }
114	
115	    float score() const override {
116	      return 0.0f;
117	    }
118	
119	    void next() override {
120	      if (iter_ && iter_->has_value) {
121	        roaring_advance_uint32_iterator(iter_);
122	      }
123	    }
124	
125	    bool valid() const override {
126	      return iter_ ? iter_->has_value : false;
127	    }
128	
129	   private:
130	    const std::shared_ptr<const InvertedSearchResult> result_{};
131	    roaring_uint32_iterator_t *iter_{nullptr};
132	  };
133	
134	
135	  IteratorUPtr create_iterator() override {
136	    return std::make_unique<InvertedIndexIterator>(shared_from_this());
137	  }
138	
139	
140	  void extract_ids(std::vector<uint32_t> *ids) const {
141	    if (!ids) {
142	      LOG_ERROR("Failed to extract ids: ids pointer is null");
143	      return;
144	    }
145	    if (!bitmap_) {
146	      return;
147	    }
148	
149	    ids->reserve(static_cast<size_t>(count()));
150	    roaring_uint32_iterator_t *iter = roaring_create_iterator(bitmap_);
151	    while (iter->has_value) {
152	      ids->push_back(iter->current_value);
153	      roaring_advance_uint32_iterator(iter);
154	    }
155	    roaring_free_uint32_iterator(iter);
156	  }
157	
158	
159	  void set_and_own_bitmap(roaring_bitmap_t *bitmap) {
160	    destroy_bitmap();
161	    bitmap_ = bitmap;
162	  }
163	
164	
165	  void destroy_bitmap() {
166	    if (bitmap_) {
167	      roaring_bitmap_free(bitmap_);
168	      bitmap_ = nullptr;
169	    }
170	  }
171	
172	
173	  void AND(const InvertedSearchResult &other) {
174	    if (!bitmap_ || !other.bitmap_) {
175	      destroy_bitmap();
176	    } else {
177	      roaring_bitmap_and_inplace(bitmap_, other.bitmap_);
178	    }
179	  }
180	
181	
182	  void OR(const InvertedSearchResult &other) {
183	    if (!other.bitmap_) {
184	      return;
185	    }
186	    if (!bitmap_) {
187	      bitmap_ = roaring_bitmap_copy(other.bitmap_);
188	      return;
189	    }
190	    roaring_bitmap_or_inplace(bitmap_, other.bitmap_);
191	  }
192	
193	
194	 private:
195	  roaring_bitmap_t *bitmap_{nullptr};
196	};
197	
198	
199	}  // namespace zvec

