Result<std::vector<FtsResult>> FtsColumnIndexer::search(
    const FtsAstNode &ast, const FtsQueryParams &query_params) const {
  if (!scorer_) {
    LOG_ERROR("FtsColumnIndexer::search: not opened. field[%s]",
