        "FtsColumnIndexer::search: not opened. field=", field_name_));
  }

  if (query_params.topk == 0) {
    return std::vector<FtsResult>{};
  }

  if (ast.must_not) {
    LOG_WARN(
        "FtsColumnIndexer::search: must_not on root is not allowed. field[%s]",
        field_name_.c_str());
