116	arrow::Result<std::shared_ptr<arrow::Array>> create_array_from_list_node(
117	    DataType data_type, const QueryListNode *list_node) {
118	  auto const &value_expr_list = list_node->value_expr_list();
119	  switch (data_type) {
120	    case DataType::INT32:
121	      return to_arrow_array<arrow::Int32Type>(value_expr_list);
122	    case DataType::UINT32:
123	      return to_arrow_array<arrow::UInt32Type>(value_expr_list);
124	    case DataType::INT64:
125	      return to_arrow_array<arrow::Int64Type>(value_expr_list);
126	    case DataType::UINT64:
127	      return to_arrow_array<arrow::UInt64Type>(value_expr_list);
128	    case DataType::FLOAT:
129	      return to_arrow_array<arrow::FloatType>(value_expr_list);
130	    case DataType::DOUBLE:
131	      return to_arrow_array<arrow::DoubleType>(value_expr_list);
132	    case DataType::STRING:
133	      return to_arrow_string_array(value_expr_list);
134	    case DataType::BOOL:
135	      return to_arrow_bool_array(value_expr_list);
136	    default:
137	      LOG_ERROR("Unsupported data type for list node. %d", (int)data_type);
138	      return arrow::Status::Invalid("Unsupported data type for list node.");
139	  }
140	}
