333	    const std::vector<Segment::Ptr> &segments, const std::string &trace_id,
334	    std::vector<sqlengine::QueryInfo::Ptr> *query_infos) {
335	  // make logic plan from query_info
336	  // PlanInfo::Ptr logical_plan = make_logical_plan(query_info);
337	
338	  // do logic optimization here
339	
