48	template <typename T>
49	auto convert_node_to_value(const QueryNode::Ptr &node) {
50	  const std::string &str = node->text();
51	  T value;
52	  if constexpr (std::is_same_v<T, int32_t>) {
53	    ailego::StringHelper::ToInt32(str, &value);
54	  } else if constexpr (std::is_same_v<T, int64_t>) {
55	    ailego::StringHelper::ToInt64(str, &value);
56	  } else if constexpr (std::is_same_v<T, uint32_t>) {
57	    ailego::StringHelper::ToUint32(str, &value);
58	  } else if constexpr (std::is_same_v<T, uint64_t>) {
59	    ailego::StringHelper::ToUint64(str, &value);
60	  } else if constexpr (std::is_same_v<T, float>) {
61	    ailego::StringHelper::ToFloat(str, &value);
62	  } else if constexpr (std::is_same_v<T, double>) {
63	    ailego::StringHelper::ToDouble(str, &value);
64	  } else {
65	    static_assert(!std::is_same_v<T, T>, "Unsupported type for conversion");
66	  }
67	  return value;
68	}
