71	template <typename ArrowType>
72	arrow::Result<std::shared_ptr<arrow::Array>> to_arrow_array(
73	    const std::vector<QueryNode::Ptr> &input) {
74	  using CType = typename ArrowType::c_type;
75	  typename arrow::TypeTraits<ArrowType>::BuilderType builder;
76	  ARROW_RETURN_NOT_OK(builder.Reserve(input.size()));
