23	
24	arrow::AsyncGenerator<std::optional<cp::ExecBatch>> InvertRecallNode::gen() {
25	  auto state_ptr = std::make_shared<State>();
26	  return [self = shared_from_this(), state_ptr = std::move(state_ptr)]()
27	             -> arrow::Future<std::optional<cp::ExecBatch>> {
28	    auto &state = *state_ptr;
29	
30	    if (!state.iter_) {
31	      auto invert_ret = self->prepare();
32	      if (!invert_ret) {
33	        return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
34	            arrow::Status::ExecutionError("prepare invert failed:",
35	                                          invert_ret.error().c_str()));
36	      }
37	      state.invert_result_ = invert_ret.value();
38	      state.iter_ = state.invert_result_->create_iterator();
39	    }
40	
41	    if (!state.iter_->valid()) {
42	      // return nullopt to indicate end
43	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
44	          std::nullopt);
45	    }
46	
47	    // collect a batch
48	    std::vector<int> indices;
49	    indices.reserve(self->batch_size_);
50	    for (int i = 0; state.iter_->valid() && i < self->batch_size_;
51	         state.iter_->next()) {
52	      if (self->seg_filter_ &&
53	          self->seg_filter_->is_filtered(state.iter_->doc_id())) {
54	        continue;
55	      }
56	      i++;
57	      indices.push_back(state.iter_->doc_id());
58	    }
59	    if (indices.empty()) {
60	      // return nullopt to indicate end
61	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
62	          std::nullopt);
63	    }
64	
65	    auto table = self->segment_->fetch(self->fetched_columns_, indices);
66	    if (!table) {
67	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
68	          arrow::Status::UnknownError("fetch table failed"));
69	    }
70	    auto batch = table->CombineChunksToBatch();
71	    if (!batch.ok()) {
72	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
73	          arrow::Status::ExecutionError("combine chunks to batch failed:",
74	                                        batch.status().ToString()));
75	    }
76	    cp::ExecBatch exec_batch(*batch.ValueUnsafe());
77	    return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
78	        std::move(exec_batch));
79	  };
80	}
81	
82	Result<InvertedSearchResult::Ptr> InvertRecallNode::prepare() {
83	  InvertSearch search(segment_.get());
84	  return search.exec_invert_cond_tree(query_info_->invert_cond().get());
