33	
34	VectorRecallNode::VectorRecallNode(Segment::Ptr segment,
35	                                   QueryInfo::Ptr query_info,
36	                                   DocFilter::Ptr doc_filter, int batch_size,
37	                                   bool single_stage_search)
38	    : segment_(std::move(segment)),
39	      query_info_(std::move(query_info)),
40	      doc_filter_(doc_filter),
41	      batch_size_(batch_size),
42	      // need fetch filter fields if single stage search, otherwise only fetch
43	      // selectd scalar fields, as forward filter is already performed and order
44	      // by only support vector score
45	      fetched_columns_(single_stage_search
46	                           ? query_info_->get_all_fetched_scalar_field_names()
47	                           : query_info_->get_selected_scalar_field_names()) {
48	  auto table = segment_->fetch(fetched_columns_, std::vector<int>{});
49	  schema_ = table->schema();
50	  schema_ = Util::append_field(*schema_, kFieldScore, arrow::float32());
51	  if (query_info_->is_include_vector()) {
52	    for (auto &field : query_info_->selected_vector_fields()) {
53	      if (field.field_schema_ptr->is_dense_vector()) {
54	        schema_ =
55	            Util::append_field(*schema_, field.field_name, arrow::binary());
56	      } else {
57	        schema_ =
58	            Util::append_field(*schema_, field.field_name, Util::sparse_type());
59	      }
60	    }
61	  }
62	  if (query_info_->group_by()) {
63	    schema_ = Util::append_field(*schema_, kFieldGroupId, arrow::utf8());
64	  }
65	}
66	
67	arrow::AsyncGenerator<std::optional<cp::ExecBatch>> VectorRecallNode::gen() {
68	  auto state_ptr = std::make_shared<State>(shared_from_this());
69	  return [state_ptr = std::move(state_ptr)]() mutable
70	         -> arrow::Future<std::optional<cp::ExecBatch>> {
71	    auto &state = *state_ptr;
72	    if (!state.iter_) {
73	      auto vector_ret = state.self_->prepare();
74	      if (!vector_ret) {
75	        return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
76	            arrow::Status::ExecutionError("prepare vector failed:",
77	                                          vector_ret.error().c_str()));
78	      }
79	      state.vector_result_ = vector_ret.value();
80	      state.iter_ = state.vector_result_->create_iterator();
81	    }
82	
83	    // check if there is any data
84	    if (!state.iter_->valid()) {
85	      // return empty optional to indicate end
86	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
87	          std::nullopt);
88	    }
89	
90	    auto record_batch = state.collect_batch();
91	    if (!record_batch.ok()) {
92	      return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
93	          arrow::Status::ExecutionError("collect batch failed:",
94	                                        record_batch.status().ToString()));
95	    }
96	    cp::ExecBatch exec_batch(*record_batch.ValueOrDie());
97	    return arrow::Future<std::optional<cp::ExecBatch>>::MakeFinished(
98	        std::move(exec_batch));
99	  };
100	}
101	
102	std::string decode_group_id_from_forward(const FieldSchema *schema,
103	                                         const arrow::Array &array) {
104	  if (array.IsNull(0)) {
105	    return "";
106	  }
107	  switch (schema->data_type()) {
108	    case DataType::INT32:
109	      return std::to_string(
110	          static_cast<const arrow::Int32Array &>(array).Value(0));
111	    case DataType::UINT32:
112	      return std::to_string(
113	          static_cast<const arrow::UInt32Array &>(array).Value(0));
114	    case DataType::INT64:
115	      return std::to_string(
116	          static_cast<const arrow::Int64Array &>(array).Value(0));
117	    case DataType::UINT64:
118	      return std::to_string(
119	          static_cast<const arrow::UInt64Array &>(array).Value(0));
120	    case DataType::STRING:
121	      return static_cast<const arrow::StringArray &>(array).GetString(0);
122	    case DataType::FLOAT:
123	      return std::to_string(
124	          static_cast<const arrow::FloatArray &>(array).Value(0));
125	    case DataType::DOUBLE:
126	      return std::to_string(
127	          static_cast<const arrow::DoubleArray &>(array).Value(0));
128	    case DataType::BOOL:
129	      return static_cast<const arrow::BooleanArray &>(array).Value(0) ? "true"
130	                                                                      : "false";
131	    default:
132	      LOG_ERROR("Unsupported data type: %d", (int)schema->data_type());
133	      return "";
134	  }
135	}
136	
137	Result<IndexResults::Ptr> VectorRecallNode::prepare() {
138	  auto filter_status = doc_filter_->compute_filter();
139	  if (!filter_status.ok()) {
140	    return tl::make_unexpected(filter_status);
141	  }
142	  auto &vector_cond_ = query_info_->vector_cond_info();
143	  CombinedVectorColumnIndexer::Ptr vector_indexer;
144	  if (auto *vector_params = dynamic_cast<const VectorIndexParams *>(
145	          vector_cond_->vector_schema()->index_params().get());
146	      vector_params == nullptr ||
147	      vector_params->quantize_type() == QuantizeType::UNDEFINED) {
148	    vector_indexer = segment_->get_combined_vector_indexer(
149	        vector_cond_->vector_field_name());
150	  } else {
151	    vector_indexer = segment_->get_quant_combined_vector_indexer(
152	        vector_cond_->vector_field_name());
153	  }
154	  if (!vector_indexer) {
155	    return tl::make_unexpected(Status::InvalidArgument(
156	        "vector index not found:", vector_cond_->vector_field_name()));
157	  }
158	  vector_column_params::QueryParams query_params;
159	  query_params.topk = query_info_->query_topn();
160	  query_params.data_type = vector_cond_->vector_schema()->data_type();
161	  query_params.dimension = vector_cond_->dimension();
162	  query_params.query_params = vector_cond_->query_params();
163	  auto brute_force_keys = doc_filter_->get_bf_by_keys_and_update(
164	      GlobalConfig::Instance().brute_force_by_keys_ratio());
165	  if (brute_force_keys) {
166	    query_params.bf_pks.emplace_back(std::move(brute_force_keys.value()));
167	  }
168	  // set filter after brute force check
169	  query_params.filter = doc_filter_->empty() ? nullptr : doc_filter_.get();
170	  if (const auto &group_by = query_info_->group_by(); group_by) {
171	    auto group_fun = [this, &group_by](uint64_t row_id) -> std::string {
172	      auto table = segment_->fetch({group_by->group_by_field},
173	                                   std::vector<int>{(int)row_id});
174	      static std::string kEmpty;
175	      if (!table) {
176	        LOG_ERROR("Fetch group by field failed: field[%s] row_id[%zu]",
177	                  group_by->group_by_field.c_str(), (size_t)row_id);
178	        return kEmpty;
179	      }
180	      if (table->num_rows() != 1) {
181	        LOG_ERROR(
182	            "Fetch group by field failed: field[%s] row_id[%zu] rows[%zu]",
183	            group_by->group_by_field.c_str(), (size_t)row_id,
184	            (size_t)table->num_rows());
185	        return kEmpty;
186	      }
187	      if (table->column(0)->chunk(0)->IsNull(0)) {
188	        return kEmpty;
189	      }
190	      return decode_group_id_from_forward(query_info_->group_by_schema_ptr(),
191	                                          *table->column(0)->chunk(0));
192	    };
193	    query_params.group_by =
194	        std::make_unique<vector_column_params::GroupByParams>(
195	            group_by->group_topk, group_by->group_count, std::move(group_fun));
196	  }
197	
198	  vector_column_params::VectorData vector_data;
199	  if (vector_cond_->vector_schema()->is_dense_vector()) {
200	    vector_data.vector =
201	        vector_column_params::DenseVector{vector_cond_->vector_term().data()};
202	  } else {
203	    vector_data.vector = vector_column_params::SparseVector{
204	        vector_cond_->sparse_count(),
205	        vector_cond_->vector_sparse_indices().data(),
206	        vector_cond_->vector_sparse_values().data()};
207	  }
208	
209	  auto vector_ret = vector_indexer->Search(vector_data, query_params);
210	  if (!vector_ret) {
211	    return tl::make_unexpected(vector_ret.error());
212	  }
213	  return vector_ret;
214	}
215	
216	arrow::Result<std::shared_ptr<arrow::RecordBatch>>
217	VectorRecallNode::State::collect_batch() {
218	  // collect a batch
219	  std::vector<int> indices;
220	  indices.reserve(self_->batch_size_);
221	  arrow::FloatBuilder builder;
222	  arrow::StringBuilder group_id_builder;
223	  for (int i = 0; iter_->valid() && i < self_->batch_size_;
224	       i++, iter_->next()) {
225	    indices.push_back(iter_->doc_id());
226	    ARROW_RETURN_NOT_OK(builder.Append(iter_->score()));
227	    if (self_->query_info_->group_by()) {
228	      ARROW_RETURN_NOT_OK(group_id_builder.Append(iter_->group_id()));
229	    }
230	  }
231	  auto table = self_->segment_->fetch(self_->fetched_columns_, indices);
232	  if (!table) {
233	    return arrow::Status::ExecutionError("fetch table failed");
234	  }
235	  auto batch = table->CombineChunksToBatch();
236	  if (!batch.ok()) {
237	    return arrow::Status::ExecutionError("combine chunks to batch failed:",
238	                                         batch.status().ToString());
239	  }
240	  auto score_array = builder.Finish();
241	  if (!score_array.ok()) {
242	    return arrow::Status::ExecutionError("finish builder failed:",
243	                                         score_array.status().ToString());
244	  }
245	  auto record_batch = std::move(batch.ValueUnsafe());
246	  ARROW_ASSIGN_OR_RAISE(
247	      record_batch,
248	      record_batch->AddColumn(record_batch->num_columns(), kFieldScore,
249	                              score_array.MoveValueUnsafe()));
250	
251	  if (self_->query_info_->is_include_vector()) {
252	    for (auto &field : self_->query_info_->selected_vector_fields()) {
253	      Result<std::shared_ptr<arrow::Array>> array_res;
254	      if (field.field_schema_ptr->is_dense_vector()) {
255	        array_res = FetchVectorOp::fetch_dense_vector(
256	            *self_->segment_, field.field_name, indices);
257	      } else {
258	        array_res = FetchVectorOp::fetch_sparse_vector(
259	            *self_->segment_, field.field_name, indices);
260	      }
261	      if (!array_res) {
262	        return arrow::Status::ExecutionError("fetch vector failed:",
263	                                             array_res.error().c_str());
264	      }
265	      ARROW_ASSIGN_OR_RAISE(
266	          record_batch,
267	          record_batch->AddColumn(record_batch->num_columns(), field.field_name,
268	                                  std::move(array_res.value())));
269	    }
270	  }
271	
272	  if (self_->query_info_->group_by()) {
273	    auto group_id_array = group_id_builder.Finish();
274	    if (!group_id_array.ok()) {
275	      return arrow::Status::ExecutionError("finish group id builder failed:",
276	                                           group_id_array.status().ToString());
277	    }
278	    ARROW_ASSIGN_OR_RAISE(
279	        record_batch,
280	        record_batch->AddColumn(record_batch->num_columns(), kFieldGroupId,
281	                                group_id_array.MoveValueUnsafe()));
282	  }
283	
284	  LOG_DEBUG("Record batch: %s", record_batch->ToString().c_str());
285	  return record_batch;
286	}
