102	std::string decode_group_id_from_forward(const FieldSchema *schema,
103	                                         const arrow::Array &array) {
104	  if (array.IsNull(0)) {
105	    return "";
106	  }
107	  switch (schema->data_type()) {
108	    case DataType::INT32:
109	      return std::to_string(
110	          static_cast<const arrow::Int32Array &>(array).Value(0));
111	    case DataType::UINT32:
112	      return std::to_string(
113	          static_cast<const arrow::UInt32Array &>(array).Value(0));
114	    case DataType::INT64:
115	      return std::to_string(
116	          static_cast<const arrow::Int64Array &>(array).Value(0));
117	    case DataType::UINT64:
118	      return std::to_string(
119	          static_cast<const arrow::UInt64Array &>(array).Value(0));
120	    case DataType::STRING:
121	      return static_cast<const arrow::StringArray &>(array).GetString(0);
122	    case DataType::FLOAT:
123	      return std::to_string(
124	          static_cast<const arrow::FloatArray &>(array).Value(0));
125	    case DataType::DOUBLE:
126	      return std::to_string(
127	          static_cast<const arrow::DoubleArray &>(array).Value(0));
128	    case DataType::BOOL:
129	      return static_cast<const arrow::BooleanArray &>(array).Value(0) ? "true"
130	                                                                      : "false";
131	    default:
132	      LOG_ERROR("Unsupported data type: %d", (int)schema->data_type());
133	      return "";
134	  }
135	}
136	
137	Result<IndexResults::Ptr> VectorRecallNode::prepare() {
138	  auto filter_status = doc_filter_->compute_filter();
139	  if (!filter_status.ok()) {
140	    return tl::make_unexpected(filter_status);
141	  }
142	  auto &vector_cond_ = query_info_->vector_cond_info();
143	  CombinedVectorColumnIndexer::Ptr vector_indexer;
144	  if (auto *vector_params = dynamic_cast<const VectorIndexParams *>(
145	          vector_cond_->vector_schema()->index_params().get());
146	      vector_params == nullptr ||
147	      vector_params->quantize_type() == QuantizeType::UNDEFINED) {
148	    vector_indexer = segment_->get_combined_vector_indexer(
149	        vector_cond_->vector_field_name());
150	  } else {
151	    vector_indexer = segment_->get_quant_combined_vector_indexer(
152	        vector_cond_->vector_field_name());
153	  }
154	  if (!vector_indexer) {
155	    return tl::make_unexpected(Status::InvalidArgument(
156	        "vector index not found:", vector_cond_->vector_field_name()));
157	  }
158	  vector_column_params::QueryParams query_params;
159	  query_params.topk = query_info_->query_topn();
160	  query_params.data_type = vector_cond_->vector_schema()->data_type();
161	  query_params.dimension = vector_cond_->dimension();
162	  query_params.query_params = vector_cond_->query_params();
163	  auto brute_force_keys = doc_filter_->get_bf_by_keys_and_update(
164	      GlobalConfig::Instance().brute_force_by_keys_ratio());
165	  if (brute_force_keys) {
166	    query_params.bf_pks.emplace_back(std::move(brute_force_keys.value()));
167	  }
168	  // set filter after brute force check
169	  query_params.filter = doc_filter_->empty() ? nullptr : doc_filter_.get();
170	  if (const auto &group_by = query_info_->group_by(); group_by) {
171	    auto group_fun = [this, &group_by](uint64_t row_id) -> std::string {
172	      auto table = segment_->fetch({group_by->group_by_field},
173	                                   std::vector<int>{(int)row_id});
174	      static std::string kEmpty;
175	      if (!table) {
176	        LOG_ERROR("Fetch group by field failed: field[%s] row_id[%zu]",
177	                  group_by->group_by_field.c_str(), (size_t)row_id);
178	        return kEmpty;
179	      }
180	      if (table->num_rows() != 1) {
181	        LOG_ERROR(
182	            "Fetch group by field failed: field[%s] row_id[%zu] rows[%zu]",
183	            group_by->group_by_field.c_str(), (size_t)row_id,
184	            (size_t)table->num_rows());
185	        return kEmpty;
186	      }
187	      if (table->column(0)->chunk(0)->IsNull(0)) {
188	        return kEmpty;
189	      }
190	      return decode_group_id_from_forward(query_info_->group_by_schema_ptr(),
191	                                          *table->column(0)->chunk(0));
192	    };
193	    query_params.group_by =
194	        std::make_unique<vector_column_params::GroupByParams>(
195	            group_by->group_topk, group_by->group_count, std::move(group_fun));
196	  }
197	
198	  vector_column_params::VectorData vector_data;
199	  if (vector_cond_->vector_schema()->is_dense_vector()) {
200	    vector_data.vector =
201	        vector_column_params::DenseVector{vector_cond_->vector_term().data()};
202	  } else {
203	    vector_data.vector = vector_column_params::SparseVector{
204	        vector_cond_->sparse_count(),
205	        vector_cond_->vector_sparse_indices().data(),
206	        vector_cond_->vector_sparse_values().data()};
207	  }
208	
209	  auto vector_ret = vector_indexer->Search(vector_data, query_params);
210	  if (!vector_ret) {
211	    return tl::make_unexpected(vector_ret.error());
212	  }
213	  return vector_ret;
214	}
