194	Status QueryAnalyzer::set_forward_filter_meta(const CollectionSchema &schema,
195	                                              QueryInfo *query_info,
196	                                              QueryNode *filter_cond) {
197	  if (filter_cond == nullptr) {
198	    return Status::OK();
199	  }
200	
201	  if (filter_cond->type() == QueryNode::QueryNodeType::LOGIC_EXPR) {
202	    QueryNode *left_node = filter_cond->left().get();
203	    QueryNode *right_node = filter_cond->right().get();
204	    if (filter_cond->left() != nullptr) {
205	      auto ret = set_forward_filter_meta(schema, query_info, left_node);
206	      if (!ret.ok()) {
207	        return ret;
208	      }
209	    }
210	    if (filter_cond->right() != nullptr) {
211	      return set_forward_filter_meta(schema, query_info, right_node);
212	    }
213	    return Status::OK();
214	  }
215	
216	  QueryRelNode *query_rel_node = reinterpret_cast<QueryRelNode *>(filter_cond);
217	  query_rel_node->set_forward();
218	  std::string forward_field_name;
219	  auto *left_node = query_rel_node->left_node();
220	  if (left_node->op() == QueryNodeOp::Q_ID) {
221	    forward_field_name = left_node->text();
222	  } else if (left_node->op() == QueryNodeOp::Q_FUNCTION_CALL) {
223	    const QueryFuncNode *func_node =
224	        dynamic_cast<const QueryFuncNode *>(left_node);
225	    const auto &arguments = func_node->arguments();
226	    auto func_name = func_node->get_func_name();
227	    if (func_name == kFuncArrayLength) {
228	      forward_field_name = arguments[0]->text();
229	    } else {
230	      return Status::NotSupported("function ", func_name, " is not supported");
231	    }
232	  } else {
233	    return Status::NotSupported("left node ", left_node->op(),
234	                                " is not supported");
235	  }
236	  auto forward_field = schema.get_forward_field(forward_field_name);
237	  if (forward_field == nullptr) {
238	    return Status::InvalidArgument(forward_field_name, " not found in schema");
239	  }
240	  if (forward_field->has_invert_index()) {
241	    // invert condition to forward condition
242	    QueryNode *right_node =
243	        std::dynamic_pointer_cast<QueryNode>(query_rel_node->right()).get();
244	    // Revert numeric buf to numeric text
245	    QueryInfoHelper::constant_node_data_buf_2_text(
246	        forward_field->element_data_type(), forward_field->is_array_type(),
247	        right_node);
248	  }
249	
250	  // forward_field is nullptr for schema free field
251	  query_info->add_forward_filter_schema_ptr(forward_field_name, forward_field);
252	  return Status::OK();
253	}
